@Test
public void practice_pruneFullSubtreesSize3_basicCase() {
    BST<String> bst = new BST<>();
    bst.add("romeo");
    bst.add("echo");
    bst.add("tango");
    bst.pruneFullSubtreesSize3();
    assertEquals("[]", bst.toString());
    points += 1;
}

@Test
public void practice_shortestWordAlongPath_singleAndTwoNodes() {
    BST<String> bst = new BST<>();
    bst.add("romeo");
    assertEquals("romeo", bst.shortestWordAlongPath("romeo"));
    bst.add("echo");
    assertEquals("echo", bst.shortestWordAlongPath("echo"));
    assertEquals("romeo", bst.shortestWordAlongPath("romeo"));
    points += 1;
}

@Test
public void practice_countLeftNodesAtDepth_threeNodeTree() {
    BST<String> bst = new BST<>();
    bst.add("november");
    bst.add("foxtrot");
    bst.add("tango");
    assertEquals(0, bst.countLeftNodesAtDepth(0));
    assertEquals(1, bst.countLeftNodesAtDepth(1));
    points += 1;
}

@Test
public void practice_isHeightBalanced_leftHeavyChain() {
    BST<Integer> bst = new BST<>();
    assertTrue(bst.isHeightBalanced());
    bst.add(30);
    assertTrue(bst.isHeightBalanced());
    bst.add(20);
    assertTrue(bst.isHeightBalanced());
    bst.add(10);
    assertFalse(bst.isHeightBalanced());
    points += 1;
}

@Test
public void practice_getSumOfHeights_growthPattern() {
    BST<Integer> bst = new BST<>();
    assertEquals(0, bst.getSumOfHeights());
    bst.add(20);
    assertEquals(0, bst.getSumOfHeights());
    bst.add(10);
    assertEquals(1, bst.getSumOfHeights());
    bst.add(30);
    assertEquals(1, bst.getSumOfHeights());
    points += 1;
}

@Test
public void practice_fullTreeConstructor_depthZeroAndOne() {
    BST<Integer> b0 = new BST<>(0);
    assertEquals("[0]", b0.toStructuredString());
    BST<Integer> b1 = new BST<>(1);
    assertEquals("[[1]0[1]]", b1.toStructuredString());
    points += 1;
}

@Test
public void practice_removeMin_threeNodeTree() {
    BST<Integer> bst = new BST<>();
    bst.add(10);
    bst.add(5);
    bst.add(15);
    assertEquals(5, (int) bst.removeMin());
    assertEquals("[10, 15]", bst.toString());
    points += 1;
}

@Test
public void practice_getPreOrderList_rootFirst() {
    BST<Integer> bst = new BST<>();
    bst.add(10);
    bst.add(5);
    bst.add(15);
    ArrayList<Integer> list = bst.getPreOrderList();
    assertEquals(Integer.valueOf(10), list.get(0));
    assertEquals(Integer.valueOf(5), list.get(1));
    points += 1;
}

@Test
public void practice_countOddOnlyIf_oddRootRightHeavy() {
    BST<Integer> bst = new BST<>();
    bst.add(81);
    assertEquals(0, (int) bst.countOddOnlyIf());
    bst.add(101);
    assertEquals(1, (int) bst.countOddOnlyIf());
    points += 1;
}
